906	    ) -> PolarsResult<AnyValue<'_>> {
907	        Ok(match value {
908	            SQLValue::Boolean(b) => AnyValue::Boolean(*b),
909	            SQLValue::DollarQuotedString(s) => AnyValue::StringOwned(s.clone().value.into()),
