932	                if s.contains('.') {
933	                    s.parse::<f64>()
934	                        .map(|n: f64| AnyValue::Float64(if negate { -n } else { n }))
935	                        .map_err(|_| ())
936	                } else {
937	                    s.parse::<i64>()
938	                        .map(|n: i64| AnyValue::Int64(if negate { -n } else { n }))
939	                        .map_err(|_| ())
940	                }
941	                .map_err(|_| polars_err!(SQLInterface: "cannot parse literal: {:?}", s))?
942	            },
943	            SQLValue::SingleQuotedByteStringLiteral(b) => {
944	                // note: for PostgreSQL this represents a BIT literal (eg: b'10101') not BYTE
945	                let bytes_literal = bitstring_to_bytes_literal(b)?;
