469	fn any_values_to_date(values: &[AnyValue], strict: bool) -> PolarsResult<DateChunked> {
470	    let mut builder = PrimitiveChunkedBuilder::<Int32Type>::new(PlSmallStr::EMPTY, values.len());
471	    for av in values {
472	        match av {
473	            AnyValue::Date(i) => builder.append_value(*i),
474	            AnyValue::Null => builder.append_null(),
475	            av => {
476	                if strict {
477	                    return Err(invalid_value_error(&DataType::Date, av));
478	                }
479	                match av.cast(&DataType::Date) {
480	                    AnyValue::Date(i) => builder.append_value(i),
481	                    _ => builder.append_null(),
482	                }
483	            },
484	        }
485	    }
486	    Ok(builder.finish().into_date())
487	}
